<?php $this->layout('default'); use Moves\Services\CmsContent; use Moves\Support\CmsView as V; $status = ['draft' => 'Rascunho', 'published' => 'Publicada']; ?>
<form class="cms-card" method="post" action="/acao/faq-save"><h2>Nova pergunta</h2><?= V::csrf() ?><?= V::field('Pergunta', 'question', '', ['required' => true]) ?><?= V::field('Resposta', 'answer', '', ['type' => 'textarea', 'required' => true]) ?><div class="cms-form-grid"><?= V::field('Ordem', 'sort_order', '0', ['type' => 'number']) ?><?= V::field('Situação', 'status', 'draft', ['type' => 'select', 'choices' => $status]) ?></div><button class="cms-btn-primary">Salvar</button></form>
<?php foreach (CmsContent::faqs() as $faq): ?><details class="cms-card"><summary><?= V::e($faq['question']) ?> <?= V::badge($faq['status'], $status[$faq['status']] ?? $faq['status']) ?></summary><form method="post" action="/acao/faq-save"><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $faq['id'] ?>"><?= V::field('Pergunta', 'question', $faq['question']) ?><?= V::field('Resposta', 'answer', $faq['answer'], ['type' => 'textarea']) ?><div class="cms-form-grid"><?= V::field('Ordem', 'sort_order', $faq['sort_order'], ['type' => 'number']) ?><?= V::field('Situação', 'status', $faq['status'], ['type' => 'select', 'choices' => $status]) ?></div><button class="cms-btn-primary">Salvar</button></form><?= V::actionButton('faq-delete', 'Excluir', ['id' => $faq['id']], 'cms-btn-danger', 'Excluir esta pergunta?') ?></details><?php endforeach; ?>
